package org.apache.commons.compress.archivers.ar;

import java.io.*;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.ar.ArArchiveInputStream;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ArArchiveInputStream_close_TriageGen1Test {

    @Test
    public void testClose_FirstTime_CallsInputClose() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act
        inputStream.close();

        // Assert
        verify(mockInput, times(1)).close();
    }

    @Test
    public void testClose_SecondTime_DoesNotCallInputCloseAgain() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act
        inputStream.close(); // First call sets closed = true
        inputStream.close(); // Second call should do nothing

        // Assert
        verify(mockInput, times(1)).close();
    }

    @Test
    public void testClose_InputThrowsIOException() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        doThrow(new IOException("Simulated IO error")).when(mockInput).close();
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act & Assert
        try {
            inputStream.close();
        } catch (IOException e) {
            assert(e.getMessage().equals("Simulated IO error"));
        }

        // Even if it throws, the internal 'closed' flag is set to true before calling input.close()
        // Therefore, a second call should not attempt to close the input again.
        try {
            inputStream.close();
        } catch (IOException e) {
            // Should not reach here because 'closed' is true
        }

        verify(mockInput, times(1)).close();
    }
}
